{std::uint64_t n=x->size();vectors.write(reinterpret_cast<char*>(&n),8);vectors.write(reinterpret_cast<const char*>(x->data()),8*n);}vectors.close();std::ofstream boundary(std::string(argv[2])+".boundary48.bin",std::ios::binary);for(const auto&e:r.boundary_events){for(int x:{e.iteration,e.row,e.side}){std::int64_t v=x;boundary.write(reinterpret_cast<char*>(&v),8);}for(double x:{e.slack,e.outward_travel,e.raw_fraction})boundary.write(reinterpret_cast<char*>(&x),8);}boundary.close();auto t=r.working_face_trace;std::ofstream ref(std::string(argv[2])+".refinement120.bin",std::ios::binary);auto ru=[&](std::uint64_t x){ref.write(reinterpret_cast<char*>(&x),8);};auto rd=[&](double x){ref.write(reinterpret_cast<char*>(&x),8);};ru(t?t->refinements.size():0);if(t)for(const auto&e:t->refinements){for(int x:{e.iteration,e.step,e.rank,e.dimension,e.reason})ru(x);for(bool x:{e.before_available,e.correction_available,e.after_available,e.accepted})ru(x);for(double x:{e.before,e.after,e.correction_inf,e.solution_inf,e.correction_cap,e.initial_double_residual})rd(x);}ref.close();if(!t)throw std::runtime_error("trace unavailable");std::ofstream saved(std::string(argv[2])+".retained64.bin",std::ios::binary);for(const auto&e:t->endpoints){std::uint64_t it=e.iteration,row=e.row;saved.write(reinterpret_cast<char*>(&it),8);saved.write(reinterpret_cast<char*>(&row),8);for(double x:{e.start,e.travel,e.endpoint,e.lower,e.upper,e.violation})saved.write(reinterpret_cast<char*>(&x),8);}saved.close();std::cout<<std::setprecision(17)<<"complete="<<r.complete<<" error="<<std::quoted(r.error)<<" events="<<r.events.size()<<" rank_events="<<r.rank_events.size()<<" retained="<<t->endpoints.size()<<" boundary_events="<<r.boundary_events.size();
